    tourFriendlyModeTitle: 'מעדיף ניסוח פשוט יותר?',
    tourFriendlyModeBody: "המתג המודגש מפעיל מצב 'שפה פשוטה', שמחליף מונחים טכניים (כמו 'MAPE' או 'רזרבה') במילים יומיומיות. לחץ עכשיו כדי לנסות — אפשר לכבות בכל עת.",

