    tourWelcomeBody: 'Ope te ayuda a saber qué tan concurrido estará tu negocio — para que puedas pedir el stock correcto, programar el personal adecuado y nunca ser sorprendido. Echemos un vistazo rápido a lo que hay aquí.',
    tourQuickActionsTitle: 'Tus acciones rápidas',
    tourQuickActionsBody: 'Estos tres botones son tus herramientas cotidianas. "Registrar venta" cuenta cada venta en tiempo real. "Registrar hoy" introduce los totales del día después de cerrar. "Registrar habitual" anota la visita de un cliente fiel.',
