    simpleModePromptOn: 'Activar', simpleModePromptDismiss: 'Ahora no',
    tourSkipSection: 'Omitir {section}',
    tourPredWeekTitle: 'Tu previsión semanal, en detalle',
    tourPredWeekBody: 'Aquí ves cada día próximo como una barra — más alta significa más concurrido. Pasa el cursor por cualquier barra para ver el rango esperado. Ope mezcla varios métodos de previsión y se apoya automáticamente en el que ha sido más preciso para tu negocio recientemente.',
    tourPredOrderingTitle: 'Qué pedir — por producto',
    tourPredOrderingBody: 'Desplázate hacia abajo para ver el consejo de pedido para cada uno de tus productos. Una vez que hayas registrado algunas ventas, Ope calcula cuánto necesitarás antes de que llegue tu próxima entrega y te dice exactamente cuándo reponer.',
    tourInsightsDayPatternsTitle: 'Tu patrón por día de la semana',
    tourInsightsDayPatternsBody: 'Ve qué día de la semana suele ser el más concurrido y cuál el más tranquilo, basado en tus propios datos — no en suposiciones. A medida que registras más días, estos patrones se vuelven más fiables.',
    tourInsightsHoursTitle: 'Tus horas punta',
    tourInsightsHoursBody: 'Una vez que hayas usado "Registrar venta" durante algunas semanas, Ope mostrará tus horas más concurridas y tranquilas del día. Úsalo para planificar el tiempo de preparación o saber cuándo necesitas todo el equipo.',
    tourInsightsYoYTitle: 'Comparación año a año',
    tourInsightsYoYBody: 'Una vez que tengas un año de historial, Ope compara este mes con el mismo mes del año pasado — para que sepas si tu negocio está creciendo, estable o bajando, sin hacer los cálculos tú mismo.',
    tourInsightsAccuracyTitle: 'Precisión de la previsión con el tiempo',
    tourInsightsAccuracyBody: 'Esto muestra qué tan precisas han sido tus previsiones. Ope suele empezar siendo aproximado y mejorar a medida que aprende tus patrones — verás la mejora aquí como un porcentaje real.',
    tourInsightsTrendsTitle: 'Cambios que vale la pena notar',
    tourInsightsTrendsBody: 'Estas son cosas que están cambiando realmente — un día de la semana que ha ido subiendo o bajando en los últimos tres meses, un cliente habitual que se ha vuelto silencioso, o una temporada alta que se acerca.',
    tourHistAddDayTitle: 'Añadir un día anterior',
    tourHistAddDayBody: '¿Olvidaste registrar ayer? Usa "Añadir día anterior" para completar cualquier día que hayas omitido. Elige la fecha del calendario, introduce el recuento de clientes y lo que vendiste, y se une a tu historial.',
    tourHistTrendsTitle: 'Tendencias mensuales',
    tourHistTrendsBody: 'Ve tus datos desglosados por mes — promedio de clientes por día, totales y cómo se compara cada mes con el anterior. Útil para detectar tu temporada más concurrida o un período de calma que no habías notado conscientemente.',
    tourHistImportTitle: 'Importar datos históricos',
    tourHistImportBody: '¿Tienes registros en una hoja de cálculo? Sube un archivo CSV aquí para traer meses o años de historial a la vez — para no tener que empezar desde cero. Ope previsualiza el archivo primero para que puedas comprobar que las fechas se ven bien antes de guardar nada.',
    tourManageProductsTitle: 'Mis productos',
    tourManageProductsBody: 'Añade aquí cada artículo que vendes — solo un nombre y una unidad para empezar. Opcionalmente añade el plazo de entrega del proveedor, el stock actual y la vida útil. Una vez añadido un producto, Ope rastrea la demanda por producto y te dice cuándo reponer.',
    tourManageRegularsTitle: 'Mis habituales',
    tourManageRegularsBody: 'Añade tus clientes fieles como "habituales" para rastrear su frecuencia de visita y cuánto valen para tu negocio con el tiempo. Ope te avisará si un habitual no ha visitado en un tiempo.',
    tourManageRecurringTitle: 'Patrones recurrentes',
    tourManageRecurringBody: '¿Hay una excursión escolar cada domingo? ¿Un día de mercado que siempre trae clientes extra? Decláralo aquí y Ope lo esperará — deja de marcar ese día como inusual y pliega el pico en tu previsión normal.',
    tourManageEventsTitle: 'Promos y eventos',
    tourManageEventsBody: 'Etiqueta aquí eventos puntuales y campañas publicitarias. Ope mide cuánto negocio extra trajo cada uno, comparado con lo que normalmente esperarías. Ideal para saber qué promociones vale la pena repetir.',
    tourManageSimpleLangTitle: 'Modo de lenguaje sencillo',
    tourManageSimpleLangBody: 'En Gestionar → Ajustes, encontrarás el interruptor "Lenguaje sencillo". Actívalo y Ope reemplaza los términos técnicos — como "MAPE", "margen de seguridad" o "FIFO" — con palabras cotidianas sencillas.',
    tourSectionPreferences: 'Preferencias', tourDarkModeTitle: '¿Oscuro o claro?',
    tourDarkModeBody: 'Ope funciona en modo claro y oscuro. El botón resaltado cambia entre ellos — ¡pruébalo ahora! Puedes cambiarlo en cualquier momento.',
    tourFriendlyModeTitle: '¿Prefieres un lenguaje más sencillo?',
    tourFriendlyModeBody: 'El interruptor resaltado activa el modo de lenguaje sencillo, que reemplaza los términos técnicos por palabras cotidianas. Pruébalo ahora — puedes desactivarlo en cualquier momento.',
    tourSettingsGearTitle: 'Tus ajustes — siempre a un clic',
    tourSettingsGearBody: 'El icono de engranaje en la barra superior abre Ajustes desde cualquier pantalla. Aquí es donde configuras tu horario de apertura, objetivos de personal, apariencia, Telegram y tu plan.',
    tourSettingsScheduleTitle: 'Tu horario de apertura',
    tourSettingsScheduleBody: 'Dile a Ope qué días abres y tu horario de apertura y cierre. Esto es crítico — los días que marcas como cerrados se omiten completamente en la previsión.',
    tourSettingsStaffingTitle: 'Objetivo de personal',
    tourSettingsStaffingBody: '¿Cuánta espera es aceptable para ti? Establece un tiempo máximo de espera o un número máximo de personas en cola. Ope usa esto, junto con tus datos de ventas, para decirte cuánto personal programar cada hora.',
    tourSettingsStockNudgesTitle: 'Gestión de stock',
    tourSettingsStockNudgesBody: 'Activa la gestión de stock para rastrear el inventario de todos tus productos y obtener consejo de pedido basado en tu ritmo de ventas y plazos de entrega.',
    tourSettingsNudgesTitle: 'Alertas proactivas',
    tourSettingsNudgesBody: 'Las alertas te envían lo único que vale la pena atender — un día inusualmente concurrido que se acerca, o stock a punto de agotarse. Se activan solo cuando hay una razón real.',
    tourSettingsAppearanceTitle: 'Modo oscuro y lenguaje sencillo',
    tourSettingsAppearanceBody: 'Cambia entre modo oscuro y claro aquí. También puedes activar el modo de lenguaje sencillo — reemplaza cada término técnico con una palabra cotidiana.',
    tourSettingsPlanTitle: 'Tu plan',
    tourSettingsPlanBody: 'Ope es gratuito para una ubicación con hasta 1 año de historial y una generosa cuota de eventos y anuncios — todas las funciones incluidas. Premium añade múltiples ubicaciones e historial extendido.',
    tourSettingsTelegramTitle: 'Conectar Telegram',
    tourSettingsTelegramBody: 'Vincula tu cuenta al bot de Ope en Telegram para poder registrar ventas y obtener tu previsión diaria por chat. Genera un código de enlace aquí y envíalo al bot.',
