    tourBusyHoursBody: 'هنا سترى أي ساعات غدًا من المتوقع أن تكون الأكثر ازدحامًا وكم موظفًا قد تحتاجه في وقت الذروة. يستخدم بيانات النقر لحظة بلحظة التي تسجلها مع "تسجيل عملية بيع".',
    tourPredictionsTitle: 'التوقعات',
    tourPredictionsBody: 'تعرض علامة تبويب التوقعات توقعك الأسبوعي بالتفصيل، بالإضافة إلى ما يجب طلبه لكل منتج ومتى. يتعلم Ope أنماطك ويحدّث هذا تلقائيًا كلما سجلت المزيد من الأيام.',
    tourInsightsTitle: 'الرؤى — ما تعلّمه Ope',
    tourInsightsBody: 'تعرض هذه الشاشة ما اكتشفه Ope عن عملك من بياناتك الحقيقية: يومك الأكثر ازدحامًا، ساعات الذروة، النمو السنوي، وتحذيرات مبكرة عن الأمور المتغيرة.',
    tourHistoryTitle: 'السجل',
    tourHistoryBody: 'تحت السجل، يمكنك عرض جميع أيامك المسجَّلة سابقًا، وإضافة يوم نسيته، ورؤية الاتجاهات الشهرية، أو استيراد جدول بيانات كامل من البيانات السابقة دفعة واحدة.',
    tourManageTitle: 'الإدارة',
    tourManageBody: 'تحت الإدارة ستجد منتجاتك، عملاءك الدائمين المخلصين، الأنماط المتكررة، العروض، والإعدادات. هنا تعلّم Ope عن عملك — كلما أضفت أكثر، ازداد ذكاء التطبيق.',
    tourDoneTitle: 'أنت جاهز تمامًا!',
    tourDoneBody: 'يصبح Ope أذكى كلما سجّلت أكثر. ابدأ بتسجيل مبيعات اليوم — ثم عد بعد أسبوعين لرؤية توقعك الأول. يمكنك إعادة تشغيل هذه الجولة في أي وقت من الإعدادات.',
