    tourQuickActionsBody: 'Эти три кнопки — ваши повседневные инструменты. «Записать продажу» считает каждую продажу в реальном времени. «Внести сегодня» вносит сегодняшние итоги после закрытия. «Записать постоянного клиента» отмечает визит лояльного клиента.',
