    tourForecastBody: 'Как только вы внесёте несколько дней, этот график покажет, насколько загруженным, вероятно, будет каждый день предстоящей недели — чтобы вы могли планировать заранее. Чем больше вы вносите данных, тем точнее прогноз.',
    tourBusyHoursTitle: 'Загруженные часы',
    tourBusyHoursBody: 'Здесь вы увидите, какие часы завтра ожидаются самыми загруженными и сколько персонала может понадобиться в пик. Используются данные нажатий из «Записать продажу».',
    tourPredictionsTitle: 'Прогнозы',
    tourPredictionsBody: 'Вкладка «Прогнозы» показывает ваш недельный прогноз в деталях, а также что и когда заказывать для каждого товара. Ope изучает ваши паттерны и автоматически обновляет их по мере внесения новых дней.',
    tourInsightsTitle: 'Аналитика — что узнал Ope',
