    tourHistoryTitle: 'История',
    tourHistoryBody: 'В разделе «История» вы можете просмотреть все свои прошлые записанные дни, добавить забытый день, увидеть месячные тренды или сразу импортировать целую таблицу прошлых данных.',
    tourManageTitle: 'Управление',
