    tourManageRegularsTitle: 'Мои постоянные клиенты',
    tourManageRegularsBody: 'Добавьте своих лояльных клиентов как «постоянных», чтобы отслеживать частоту их визитов и то, сколько они приносят вашему бизнесу со временем. Ope предупредит вас, если постоянный клиент давно не приходил — тихий сигнал, что он может уходить. Их визиты никогда не смешиваются с вашей историей спроса.',
    tourManageRecurringTitle: 'Повторяющиеся паттерны',
